1460	+/// One parsed SSE event from `chat.messages.send`'s streaming response
1461	+/// (`openapi.yaml`: `message_created -> context -> token* -> done|error`,
1462	+/// in this order). `context` is intentionally never modeled here — the
1463	+/// Boundaries explicitly exclude "rendering the SSE `context` event's
1464	+/// retrieval/citation data"; `ChatRemoteDataSource` receives and discards
1465	+/// it before it would ever become one of these. `error` likewise never
1466	+/// becomes a member of this type — it's a terminal failure, surfaced as
1467	+/// `Left(Failure.fromCode(...))` by the same stream this event type flows
1468	+/// through (`ChatRepository.sendMessage`'s own `Stream<Either<Failure,
1469	+/// ChatStreamEvent>>`), never wrapped as a `Right` value.
1470	+///
1471	+/// A plain sealed class, not `freezed` (mirrors `core/resource.dart`'s own
1472	+/// `Resource<T>` — AD-12's prose: "Chat's state is its own sealed class,
1473	+/// never forced into `Resource<T>`" extends to this smaller stream-event
1474	+/// type too, no union/copyWith machinery needed for 3 fixed, flat shapes).
1475	+sealed class ChatStreamEvent {
1476	+  const ChatStreamEvent();
1477	+}
1478	+
1479	+/// Design Notes: "`message_created` carries the persisted user-message
1480	+/// id" — the id the backend just assigned to the user's own just-sent
1481	+/// message (not the AI response being generated). Unused by this story's
1482	+/// own `ChatCubit` (no retry-by-id feature yet, Boundaries) — modeled now
1483	+/// so Story 6.3's retry call has a value to key off without re-parsing the
1484	+/// stream.
1485	+class ChatMessageCreatedEvent extends ChatStreamEvent {
1486	+  const ChatMessageCreatedEvent(this.userMessageId);
1487	+
1488	+  final String userMessageId;
1489	+
1490	+  @override
1491	+  bool operator ==(Object other) =>
1492	+      identical(this, other) ||
1493	+      (other is ChatMessageCreatedEvent &&
1494	+          other.userMessageId == userMessageId);
1495	+
1496	+  @override
1497	+  int get hashCode => userMessageId.hashCode;
1498	+
1499	+  @override
1500	+  String toString() => 'ChatMessageCreatedEvent(userMessageId: $userMessageId)';
1501	+}
1502	+
1503	+/// One `token` event's `delta` — Design Notes: "this spec assumes `token`
1504	+/// carries a `delta` text field". `ChatCubit` appends [delta] onto the
1505	+/// streaming AI bubble's content on every emission.
1506	+class ChatTokenEvent extends ChatStreamEvent {
1507	+  const ChatTokenEvent(this.delta);
1508	+
1509	+  final String delta;
1510	+
1511	+  @override
1512	+  bool operator ==(Object other) =>
1513	+      identical(this, other) || (other is ChatTokenEvent && other.delta == delta);
1514	+
1515	+  @override
1516	+  int get hashCode => delta.hashCode;
1517	+
1518	+  @override
1519	+  String toString() => 'ChatTokenEvent(delta: $delta)';
1520	+}
1521	+
1522	+/// The stream's own successful terminator — marks the AI bubble `complete`.
1523	+class ChatDoneEvent extends ChatStreamEvent {
1524	+  const ChatDoneEvent();
1525	+
1526	+  @override
1527	+  bool operator ==(Object other) => other is ChatDoneEvent;
1528	+
1529	+  @override
1530	+  int get hashCode => (ChatDoneEvent).hashCode;
1531	+
1532	+  @override
1533	+  String toString() => 'ChatDoneEvent()';
1534	+}
