1642	+  /// instead of starting a second bootstrap, so two near-simultaneous
1643	+  /// callers (e.g. two mounts before the first resolves) never both
1644	+  /// observe "no sessions" and both call `createSession()` (Boundaries:
1645	+  /// "silently ensure *one* Chat Session exists").
1646	+  Future<void>? _initFuture;
1647	+
1648	+  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
1649	+  /// exists (reuse the most recent from `chat-sessions-list`, else
1650	+  /// `chat-sessions-create` with no title)". A no-op once already
1651	+  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
1652	+  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
1653	+  /// from an earlier visit.
1654	+  Future<void> init() {
1655	+    if (state is ChatReady || isClosed) {
1656	+      return Future.value();
1657	+    }
1658	+    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
1659	+  }
1660	+
1661	+  Future<void> _bootstrap() async {
1662	+    emit(const ChatBootstrapLoading());
1663	+
1664	+    final sessionsResult = await _repository.listSessions();
1665	+    if (isClosed) {
1666	+      return;
1667	+    }
1668	+    final Either<Failure, ChatSession> sessionResult = await sessionsResult
1669	+        .match((failure) async => left(failure), (sessions) async {
1670	+          if (sessions.isEmpty) {
