1	// The constructor keeps public named params (`dio`, `urlBuilder`) distinct
2	// from the private fields they initialize, so an initializing formal
3	// (which would force the external name to match) isn't a clean fit here.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:convert';
6	
7	import 'package:dio/dio.dart';
8	import 'package:fpdart/fpdart.dart';
9	
10	import '../failure/failure.dart';
11	import '../session/session_expiry_notifier.dart';
12	import 'dio_error_code.dart';
13	import 'header_interceptor.dart';
14	import 'url_builder.dart';
15	
16	/// AD-2/AD-5 — the one network façade every repository's data source calls
17	/// through. Builds the real URL via `UrlBuilder`, sends the request through
18	/// `dio` (header + retry interceptors already attached in DI), and maps
19	/// every outcome — success or failure — to `Either<Failure, T>`; no
20	/// dio/native exception ever escapes unmapped (RNF09).
21	///
22	/// Story 1.5: also the one detection point for a mid-session `AUTH_EXPIRED`
23	/// — signals [SessionExpiryNotifier] when one is seen outside
24	/// `HeaderInterceptor.anonKeyOnlyFunctions`, so the boot-time `auth-refresh`
25	/// call (Story 1.4's `restoreSession()`) never triggers it.
26	///
27	/// Tests mock this interface directly (per the architecture spine's testing
28	/// convention), not a fake transport layer underneath it.
29	class ApiClient {
30	  ApiClient({
31	    required Dio dio,
32	    required UrlBuilder urlBuilder,
33	    required SessionExpiryNotifier sessionExpiryNotifier,
34	  })  : _dio = dio,
35	        _urlBuilder = urlBuilder,
36	        _sessionExpiryNotifier = sessionExpiryNotifier;
37	
38	  final Dio _dio;
39	  final UrlBuilder _urlBuilder;
40	  final SessionExpiryNotifier _sessionExpiryNotifier;
41	
42	  Future<Either<Failure, Map<String, dynamic>>> get(
43	    String function, {
44	    List<String> pathParams = const [],
45	    Map<String, dynamic>? queryParameters,
46	  }) =>
47	      _send(
48	        () => _dio.get<Map<String, dynamic>>(
49	          _urlBuilder.build(function, pathParams),
50	          queryParameters: queryParameters,
51	        ),
52	      );
53	
54	  Future<Either<Failure, Map<String, dynamic>>> post(
55	    String function, {
56	    List<String> pathParams = const [],
57	    Object? data,
58	  }) =>
59	      _send(
60	        () => _dio.post<Map<String, dynamic>>(
61	          _urlBuilder.build(function, pathParams),
62	          data: data,
63	        ),
64	      );
65	
66	  Future<Either<Failure, Map<String, dynamic>>> patch(
67	    String function, {
68	    List<String> pathParams = const [],
69	    Object? data,
70	  }) =>
71	      _send(
72	        () => _dio.patch<Map<String, dynamic>>(
73	          _urlBuilder.build(function, pathParams),
74	          data: data,
75	        ),
76	      );
77	
78	  Future<Either<Failure, Map<String, dynamic>>> delete(
79	    String function, {
80	    List<String> pathParams = const [],
81	    Object? data,
82	  }) =>
83	      _send(
84	        () => _dio.delete<Map<String, dynamic>>(
85	          _urlBuilder.build(function, pathParams),
86	          data: data,
87	        ),
88	      );
89	
90	  /// spec-6-1 — streaming companion to [post]: sent with
91	  /// `ResponseType.stream` so the SSE response body never gets buffered
92	  /// into a single in-memory JSON blob the way [post]'s own
93	  /// `Dio.post<Map<String, dynamic>>` would. Each emitted `Right` is one
94	  /// raw, UTF-8-decoded chunk straight off the wire — SSE `event:`/`data:`
95	  /// line-splitting stays feature-local (`ChatRemoteDataSource`), this
96	  /// façade only owns the transport + error-mapping step (Boundaries:
97	  /// "ApiClient stays the one façade every datasource calls through").
98	  /// `allowMalformed: true` mirrors every other decode step in this app
99	  /// (RNF09: never throw on a malformed byte sequence) — a chunk that
100	  /// can't be exactly transcoded still degrades to the replacement
101	  /// character rather than crashing the stream.
102	  ///
103	  /// A connection that closes cleanly with no further error is simply a
104	  /// stream that ends with no further `Right`/`Left` emitted — detecting
105	  /// that as a "mid-stream drop" (no `done`/`error` SSE event ever seen)
106	  /// is the caller's job, not this method's; `ApiClient` has no notion of
107	  /// the SSE event grammar.
108	  Stream<Either<Failure, String>> postStream(
109	    String function, {
110	    List<String> pathParams = const [],
111	    Object? data,
112	  }) async* {
113	    try {
114	      final response = await _dio.post<ResponseBody>(
115	        _urlBuilder.build(function, pathParams),
116	        data: data,
117	        options: Options(responseType: ResponseType.stream),
118	      );
119	      final body = response.data;
120	      if (body == null) {
121	        yield left(
122	          const Failure.malformedResponse(message: 'Empty stream body'),
123	        );
124	        return;
125	      }
126	      // `Utf8Decoder.bind` (not a per-chunk `utf8.decode`) carries any
127	      // incomplete trailing multi-byte sequence over to the next chunk —
128	      // required here since dio's own chunk boundaries split on byte
129	      // count, not on character boundaries, and this app's primary
130	      // language (pt-BR) uses multi-byte UTF-8 characters constantly.
131	      await for (final text in const Utf8Decoder(
132	        allowMalformed: true,
133	      ).bind(body.stream)) {
134	        yield right(text);
135	      }
136	    } on DioException catch (e) {
137	      yield left(await _mapStreamDioException(e));
138	    } catch (e) {
139	      yield left(Failure.malformedResponse(message: e.toString()));
140	    }
141	  }
142	
143	  /// [postStream]'s own error-mapping step. A non-2xx response to a
144	  /// `ResponseType.stream` request is never auto-decoded into a `Map` by
145	  /// dio's default transformer (dio's own contract: "you must return the
146	  /// responseBody when Options.responseType is stream") — [e.response]'s
147	  /// `data` is still the raw, undrained [ResponseBody] at this point, so
148	  /// [_mapDioException]'s own `data is Map` check always misses it and
149	  /// would otherwise collapse every real backend error code on this one
150	  /// streaming endpoint into [Failure.malformedResponse]. Draining and
151	  /// decoding it here, once, keeps that same `{code, message}` mapping
152	  /// (`error-taxonomy.md`) correct for the stream path too, without
153	  /// changing [_mapDioException]/`dioErrorCodeOf` themselves — both are
154	  /// shared with `RetryInterceptor`, which never sees a stream response at
155	  /// all (it retries before dio's transformer runs), so widening their
156	  /// `Map`-only contract isn't needed here. Any failure to drain/decode
157	  /// (including a non-JSON body) falls back to [_mapDioException]'s own
158	  /// generic mapping unchanged.
159	  Future<Failure> _mapStreamDioException(DioException e) async {
160	    final data = e.response?.data;
161	    if (data is ResponseBody) {
162	      try {
163	        final bytes = await data.stream.expand((chunk) => chunk).toList();
164	        final decoded = jsonDecode(utf8.decode(bytes, allowMalformed: true));
165	        if (decoded is Map && decoded['code'] is String) {
166	          final message = decoded['message'];
167	          final failure = Failure.fromCode(
168	            decoded['code'] as String,
169	            (message is String ? message : null) ?? 'Unknown error',
170	          );
171	          if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
172	            _sessionExpiryNotifier.notifyExpired();
173	          }
174	          return failure;
175	        }
176	      } catch (_) {
177	        // Falls through to the generic mapping below — same "never throw"
178	        // rationale every other decode step in this file already follows.
179	      }
180	    }
181	    return _mapDioException(e);
182	  }
183	
184	  Future<Either<Failure, Map<String, dynamic>>> _send(
185	    Future<Response<Map<String, dynamic>>> Function() request,
186	  ) async {
187	    try {
188	      final response = await request();
189	      final data = response.data;
190	      if (data == null) {
191	        return left(
192	          const Failure.malformedResponse(message: 'Empty response body'),
193	        );
194	      }
195	      return right(data);
196	    } on DioException catch (e) {
197	      return left(_mapDioException(e));
198	    } catch (e) {
199	      return left(Failure.malformedResponse(message: e.toString()));
200	    }
201	  }
202	
203	  Failure _mapDioException(DioException e) {
204	    final code = dioErrorCodeOf(e);
205	    if (code == null) {
206	      // Covers a cancelled request and an HTTP response that doesn't carry
207	      // the expected `{code, message, retryable}` body — neither is one of
208	      // the 13 backend codes, so neither is retryable (dioErrorCodeOf).
209	      return Failure.malformedResponse(
210	        message: e.message ?? 'Malformed response',
211	      );
212	    }
213	    final data = e.response?.data;
214	    final message = data is Map ? data['message'] : null;
215	    final failure = Failure.fromCode(
216	      code,
217	      (message is String ? message : null) ?? e.message ?? 'Unknown error',
218	    );
219	    if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
220	      _sessionExpiryNotifier.notifyExpired();
221	    }
222	    return failure;
223	  }
224	
225	  /// Whether [e]'s request targeted one of the three `security: []`
226	  /// operations (signup, login, refresh) — the only calls `AUTH_EXPIRED`
227	  /// must never be treated as a mid-session expiry for, since those are the
228	  /// anon-keyed calls Story 1.4's `restoreSession()` itself makes.
229	  ///
230	  /// Mirrors `HeaderInterceptor.onRequest`'s own fail-open behavior: a
231	  /// malformed `requestOptions.path` (shouldn't happen — `UrlBuilder`
232	  /// always produces a valid URL) is treated as "not anon-key-only" rather
233	  /// than letting a `FormatException` escape this mapping step unmapped
234	  /// (RNF09).
235	  bool _isAnonKeyOnlyCall(DioException e) {
